CREATE FUNCTION vec_dietas.llamar_r15(n text,f date,o text,s text,p text,e text,v text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE x jsonb; i jsonb; m jsonb; c jsonb; d jsonb; ms text; h text; amb text; atr text; r jsonb; BEGIN x:=jsonb_build_object('esquema','vec.contexto-actor.vinculado.v2','principal_ref','actor-a','contexto_actor_ref','ctx-a','contexto_version','1','cuenta_ref','cuenta-a','cuenta_version','1','perfil_activo_ref','perfil-a','persona_ref',p,'persona_version','1','perfil_version','1','vinculos',jsonb_build_array(jsonb_build_object('tipo','empleado','estado','activo','referencia',e))); i:=jsonb_build_object('actor_ref','actor-a','contexto_actor_ref','ctx-a','contexto_version','1','cuenta_ref','cuenta-a','cuenta_version','1','empleado_ref',e,'perfil_ref','perfil-a','perfil_version','1','persona_ref',p,'persona_version','1'); m:=jsonb_build_object('esquema','vec.personal.relacion-propia-dietas.v1','fecha_referencia',f::text,'identidad',i,'operacion',o,'relacion_ref',CASE WHEN s IS NULL THEN 'null'::jsonb ELSE to_jsonb(s) END); ms:=encode(sha256(convert_to(m::text,'UTF8')),'hex'); amb:='{"empleado_ref":'||to_jsonb(e)::text||',"persona_ref":'||to_jsonb(p)::text||'}'; atr:='{"fecha_referencia":'||to_jsonb(f::text)::text||',"material_sha256":"'||ms||'","operacion":'||to_jsonb(o)::text||',"relacion_ref":'||to_jsonb(coalesce(s,'sin_seleccion'))::text||'}'; h:=encode(sha256(convert_to('{"ambitos":'||amb||',"atributos":'||atr||'}','UTF8')),'hex'); c:=jsonb_build_object('audiencia_consumo','vec_personal.relacion_propia.consultar_dietas.v1','operacion','personal.relacion.propia.consultar_dietas','nonce',n); d:=jsonb_build_object('accion','personal.relacion.propia.consultar_dietas','campos_permitidos',jsonb_build_array('desde','empleado_ref','estado','fuente_ref','fuente_version','hasta','persona_ref','procedencia_acto_ref','relacion_ref','unidad_ref','version'),'concedida',true,'contexto_recurso_huella_sha256',h,'decision_ref','dec_'||n,'finalidad','preparar_borrador_dietas','modulo_id','personal','obligaciones','[]'::jsonb,'perfil_activo_ref','perfil-a','principal_id','actor-a','recurso_ref',e,'tipo_recurso','relacion_empleado_dietas'); IF v='actor' THEN d:=jsonb_set(d,'{principal_id}','"otro"'); ELSIF v='perfil' THEN d:=jsonb_set(d,'{perfil_activo_ref}','"otro"'); ELSIF v='version' THEN x:=jsonb_set(x,'{persona_version}','"2"'); ELSIF v='centinela' THEN d:=jsonb_set(d,'{contexto_recurso_huella_sha256}','"0"'); ELSIF v='audiencia' THEN c:=jsonb_set(c,'{audiencia_consumo}','"otra"'); ELSIF v='campos' THEN d:=jsonb_set(d,'{campos_permitidos}',d->'campos_permitidos'||'"extra"'::jsonb); ELSIF v='obligaciones' THEN d:=jsonb_set(d,'{obligaciones}','["x"]'::jsonb); END IF; SELECT to_jsonb(q) INTO r FROM vec_personal.consultar_relaciones_propias_dietas_v1(m::text,convert_to(c::text,'UTF8'),convert_to(d::text,'UTF8'),'m'::bytea,convert_to(x::text,'UTF8'),1,1,decode('5600414403','hex'),'s'::bytea,'e'::bytea,'r'::bytea) q; RETURN r; END $$;
ALTER FUNCTION vec_dietas.llamar_r15(text,date,text,text,text,text,text) OWNER TO vec_dietas_propietario; ALTER FUNCTION vec_dietas.llamar_r15(text,date,text,text,text,text,text) SECURITY INVOKER; REVOKE ALL ON FUNCTION vec_dietas.llamar_r15(text,date,text,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION vec_dietas.llamar_r15(text,date,text,text,text,text,text) TO vec_dietas_ejecutor;
CREATE FUNCTION vec_personal.r15_recibo_igual(text,timestamptz) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM vec_personal.recibo_consulta_relacion_propia_dietas WHERE referencia=$1 AND registrada_en=$2) $$; ALTER FUNCTION vec_personal.r15_recibo_igual(text,timestamptz) OWNER TO vec_personal_propietario; REVOKE ALL ON FUNCTION vec_personal.r15_recibo_igual(text,timestamptz) FROM PUBLIC; GRANT EXECUTE ON FUNCTION vec_personal.r15_recibo_igual(text,timestamptz) TO vec_dietas_ejecutor;
